content:
{
  "book_code": "2ES",
  "verses": [
    {
      "chapter": 15,
      "verse": 1,
      "text_ar": "«انظُرْ، انقُلْ على مسامعِ شعبي كلامَ النبوءةِ الذي سأضعهَ في فيك»، قالَ الربّ.",
      "review_notes_ar": []
    },
    {
      "chapter": 15,
      "verse": 2,
      "text_ar": "«اجعلْهَم يكتبونَها على الأوراقِ، لأنَّها صادقةٌ حقٌّ.",
      "review_notes_ar": []
    },
    {
      "chapter": 15,
      "verse": 3,
      "text_ar": "لا تخَفْ من كيدهم ضِمنَك. لا تَغتمَّ من عِنادِ الذي عَهْدُك يَستاءونَ منكَ.",
      "review_notes_ar": ["نص مشكوك في دقته السردية في النص الإنجليزي الأصلي، تم نقله حرفياً"]
    },
    {
      "chapter": 15,
      "verse": 4,
      "text_ar": "فإنَّ جميعَ العُصاةِ سيموتونَ على عُبوديَّتِهم.",
      "review_notes_ar": []
    },
    {
      "chapter": 15,
      "verse": 5,
      "text_ar": "«تِرةِ،» قالَ الرَّبّ، «سَأجلبُ آفاتٍ على كلّ الأرض: السيفَ، والجوعَ، والموتَ، والدمارَ.",
      "review_notes_ar": ["نص مشكوك في دقته النحوية في النص الإنجليزي الأصلي، تم نقله حرفياً"]
    },
    {
      "chapter": 15,
      "verse": 6,
      "text_ar": "لأنَّ الشرَّ قد توسَّعَ على كلِّ أمةٍ، وأعمالُهم المُوجِعَة قد بلغتِ حِدها.",
      "review_notes_ar": []
    },
    {
      "chapter": 15,
      "verse": 7,
      "text_ar": "لذلك،» قالَ الربّ،",
      "review_notes_ar": []
    },
    {
      "chapter": 15,
      "verse": 8,
      "text_ar": "«لن أكفَّ بعدُ عنِ الحُكمِ على شرِّهم الذي يَسفِّقونَهُ، ولن أَصبرَ على هَؤُلَاء في هذه الأشياءِ التي يَجرمونَ فيها عمليًّاً. أنظُرْ، دَمُ الأبرياءِ والصُّلَحاءِ يَستقرُّ إليَّ، وأرواحُ العُدَّالِ تَصرخُ دائماً.",
      "review_notes_ar": []
    },
    {
      "chapter": 15,
      "verse": 9,
      "text_ar": "سَأنتقمُ لهُم حتماً»، قالَ الربّ، «وسأُدخِلُ إليَّ كلَّ دَمٍ بريءٍ من بينِهِم.",
      "review_notes_ar": []
    },
    {
      "chapter": 15,
      "verse": 10,
      "text_ar": "انظُرْ، سِعَتي يُقادونَ كقطيعٍ إلى الذبح. لن أُسمِحَ لهُم الآنَ بالسكنى في أرضِ مصرَ،",
      "review_notes_ar": ["نص مشكوك في دقته السردية في النص الإنجليزي الأصلي، تم نقله حرفياً"]
    },
    {
      "chapter": 15,
      "verse": 11,
      "text_ar": "بل سأُخرِجُهُم بيدٍ قَويَّةٍ وبيَدٍ مرفوعةٍ، وسأضربُ مصرَ بكوارثَ، كما في السابقِ، وسأُتلفُ كلَّ أرضِها.»",
      "review_notes_ar": []
    },
    {
      "chapter": 15,
      "verse": 12,
      "text_ar": "لتَحزنِ مصرُ وأَساساتُها، على وآلَةِ تأديبٍ وعذابٍ سَيَأتِي بِها الإلهُ علَيها.",
      "review_notes_ar": []
    },
    {
      "chapter": 15,
      "verse": 13,
      "text_ar": "لتَندبِ الفلاحونَ الذينَ يَحرُثونَ الأرضَ، لأنَّ بذرَهُم سَيَفقُدُ وحدودَ أشجارِهم سَتُتلفُ عن طريقِ العفنِ والحَبةِ، وعاصفةٍ مرعبةٍ.",
      "review_notes_ar": []
    },
    {
      "chapter": 15,
      "verse": 14,
      "text_ar": "ويلٌ للعالمِ والذينَ يسكنونَ فيهِ!",
      "review_notes_ar": []
    },
    {
      "chapter": 15,
      "verse": 15,
      "text_ar": "لأنَّ السيفَ ودُمورَهم يقتربون، وأمةٌ سيرتفعونَ على أمةٍ ليقاتلوا ببعضِهم من بعضٍ بأسلحةٍ في أيديهم.",
      "review_notes_ar": []
    },
    {
      "chapter": 15,
      "verse": 16,
      "text_ar": "لأنَّ ثَورةً سيكونُ بينَ الناسِ، ومعَ تَبدُّدِهم في بعضهم بعضًاً. بِقوتِهِم، لن يَرحَموا مَلِكهم أو كبيرَ رئيسَهم.",
      "review_notes_ar": []
    },
    {
      "chapter": 15,
      "verse": 17,
      "text_ar": "لأنَّ رَجُلاً سَيَطمعُ في دخولِ مدينةٍ، ولن يَتمكَّنَ.",
      "review_notes_ar": []
    },
    {
      "chapter": 15,
      "verse": 18,
      "text_ar": "لأنَّ بِجهلِهِم المدنَ ستضطرب، والبُيوتَ ستُدمَّر، والناسَ يَخشَون.",
      "review_notes_ar": []
    },
    {
      "chapter": 15,
      "verse": 19,
      "text_ar": "جاهلٌ لن يَرحمَ جارَهُ، بل سَيَعتديَ على بيوتهِ بالسيفِ وُسُوطِ ماله، بسببَ عجزِ الخبزِ، ومن أجلِ مؤقَّتٍ عظيمٍ.",
      "review_notes_ar": []
    },
    {
      "chapter": 15,
      "verse": 20,
      "text_ar": "«تِرةِ،» قالَ الإلهُ، «أجمعُ كلَّ مَملوكي الأرضِ لِيُحرِّكوا الذينَ هوَ من مَشرِقِ الشمس، ومنَ الجنوبِ، ومنَ الشرقِ، ومنَ لُبْنان، لِيَعبروا بعضُهم على بعضٍ، ويُعِيدوا الأشياءَ التي صَنعوها لهُم.",
      "review_notes_ar": ["نص مشكوك في دقته النحوية في النص الإنجليزي الأصلي، تم نقله حرفياً: Libanus"]
    }
  ]
}
